package com.afaq.iman;import android.app.PendingIntent;import android.appwidget.AppWidgetManager;import android.appwidget.AppWidgetProvider;import android.content.Context;import android.content.Intent;import android.content.SharedPreferences;import android.os.SystemClock;import android.widget.RemoteViews;
public class PrayerWidgetProvider extends AppWidgetProvider{public void onUpdate(Context c,AppWidgetManager m,int[] ids){updateAll(c,ids);}static void updateAll(Context c,int[] ids){SharedPreferences p=c.getSharedPreferences("afaq_widget",Context.MODE_PRIVATE);String prayer=p.getString("prayer","افتح التطبيق للتحديث"),city=p.getString("city","");long target=p.getLong("target",System.currentTimeMillis());for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_prayer);v.setTextViewText(R.id.widget_prayer,prayer);v.setTextViewText(R.id.widget_city,city);v.setChronometer(R.id.widget_countdown,SystemClock.elapsedRealtime()+Math.max(0,target-System.currentTimeMillis()),null,true);Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));AppWidgetManager.getInstance(c).updateAppWidget(id,v);}}}
